    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  {
    int jj, kk;
#pragma omp parallel for private(j, k, jj, kk) schedule(dynamic, 1)
    for (i = 0; i < _PB_N; i++) {
      for (j = 0; j <= i; j++)
        C[i][j] *= beta;
      for (kk = 0; kk < _PB_M; kk += 64) {
        int kend = (kk + 64 < _PB_M) ? kk + 64 : _PB_M;
        for (jj = 0; jj <= i; jj += 256) {
          int jend = (jj + 255 < i) ? jj + 255 : i;
          for (k = kk; k < kend; k++) {
            DATA_TYPE abi = alpha * B[i][k];
            DATA_TYPE aai = alpha * A[i][k];
#pragma omp simd
            for (j = jj; j <= jend; j++)
              C[i][j] += A[j][k] * abi + B[j][k] * aai;
          }
        }
      }
    }
  }
#pragma endscop

}


