/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

//BLAS PARAMS
//TRANS = 'N'
//UPLO  = 'L'
// =>  Form  C := alpha*A*A**T + beta*C.
//A is NxM
//C is NxN
#pragma scop
  {
    int ii, jj, kk;
#pragma omp parallel for private(ii, jj, kk, i, j, k) schedule(dynamic, 1)
    for (ii = 0; ii < _PB_N; ii += 32) {
      int iend = (ii + 32 < _PB_N) ? ii + 32 : _PB_N;
      for (i = ii; i < iend; i++) {
#pragma omp simd
        for (j = 0; j <= i; j++)
          C[i][j] *= beta;
      }
      for (kk = 0; kk < _PB_M; kk += 64) {
        int kend = (kk + 64 < _PB_M) ? kk + 64 : _PB_M;
        for (jj = 0; jj < iend; jj += 256) {
          int jend = (jj + 256 < iend) ? jj + 256 : iend;
          for (i = ii; i < iend; i++) {
            int jmax = (jend < i + 1) ? jend : i + 1;
            if (jj >= jmax) continue;
            for (k = kk; k < kend; k++) {
              DATA_TYPE aik = alpha * A[i][k];
              for (j = jj; j < jmax; j++)
                C[i][j] += aik * A[j][k];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


