    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  {
    int jj;
#pragma omp parallel for schedule(static) private(i, j, k)
    for (jj = 0; jj < _PB_N; jj += 32) {
      int jend = (jj + 32 < _PB_N) ? (jj + 32) : _PB_N;
      for (i = 0; i < _PB_M; i++) {
        for (k = i + 1; k < _PB_M; k++) {
          DATA_TYPE a = A[k][i];
#pragma omp simd
          for (j = jj; j < jend; j++)
            B[i][j] += a * B[k][j];
        }
#pragma omp simd
        for (j = jj; j < jend; j++)
          B[i][j] = alpha * B[i][j];
      }
    }
  }
#pragma endscop

}


