/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
  /* D := alpha*A*B*C + beta*D */
  {
    int ii;
#pragma omp parallel for schedule(static) private(i, j, k)
    for (ii = 0; ii < _PB_NI; ii += 16)
      {
	int iend = (ii + 16 < _PB_NI) ? ii + 16 : _PB_NI;
	int kk, jj;

	/* Phase 1: tmp rows [ii, iend) := alpha*A*B */
	for (i = ii; i < iend; i++)
	  for (j = 0; j < _PB_NJ; j++)
	    tmp[i][j] = SCALAR_VAL(0.0);

	for (kk = 0; kk < _PB_NK; kk += 64)
	  {
	    int kend = (kk + 64 < _PB_NK) ? kk + 64 : _PB_NK;
	    for (jj = 0; jj < _PB_NJ; jj += 256)
	      {
		int jend = (jj + 256 < _PB_NJ) ? jj + 256 : _PB_NJ;
		for (i = ii; i < iend; i++)
		  for (k = kk; k < kend; k++)
		    {
		      DATA_TYPE a = alpha * A[i][k];
#pragma omp simd
		      for (j = jj; j < jend; j++)
			tmp[i][j] += a * B[k][j];
		    }
	      }
	  }

	/* Phase 2 (fused per row block): D rows [ii, iend) */
	for (i = ii; i < iend; i++)
	  for (j = 0; j < _PB_NL; j++)
	    D[i][j] *= beta;

	for (kk = 0; kk < _PB_NJ; kk += 64)
	  {
	    int kend = (kk + 64 < _PB_NJ) ? kk + 64 : _PB_NJ;
	    for (jj = 0; jj < _PB_NL; jj += 256)
	      {
		int jend = (jj + 256 < _PB_NL) ? jj + 256 : _PB_NL;
		for (i = ii; i < iend; i++)
		  for (k = kk; k < kend; k++)
		    {
		      DATA_TYPE t = tmp[i][k];
#pragma omp simd
		      for (j = jj; j < jend; j++)
			D[i][j] += t * C[k][j];
		    }
	      }
	  }
      }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

