  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);
#pragma omp simd reduction(+:sum)
   for (i=0; i<k; i++) {
      sum += r[k-i-1]*y[i];
   }
   alpha = - (r[k] + sum)/beta;

   {
     int half = k / 2;
     DATA_TYPE a_l = alpha;
     /* Fused z-computation and copy-back: each pair (i, k-1-i) is updated
        together from the old values, equivalent to using temporary z. */
     for (i = 0; i < half; i++) {
       DATA_TYPE lo = y[i];
       DATA_TYPE hi = y[k-1-i];
       y[i]     = lo + a_l*hi;
       y[k-1-i] = hi + a_l*lo;
     }
     if (k & 1) {
       DATA_TYPE mid = y[half];
       y[half] = mid + a_l*mid;
     }
   }
   y[k] = alpha;
 }
#pragma endscop

}


