/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
      Q[i][j] = 0.0;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      R[i][j] = 0.0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
 http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
#pragma omp parallel private(k, i, j)
  {
    for (k = 0; k < _PB_N; k++)
      {
#pragma omp single
        {
          nrm = SCALAR_VAL(0.0);
          for (i = 0; i < _PB_M; i++)
            nrm += A[i][k] * A[i][k];
          R[k][k] = SQRT_FUN(nrm);
        }

#pragma omp for schedule(static)
        for (i = 0; i < _PB_M; i++)
          Q[i][k] = A[i][k] / R[k][k];

#pragma omp for schedule(static)
        for (j = k + 1; j < _PB_N; j += 32)
          {
            int jj, ii;
            int jend = (j + 32 < _PB_N) ? (j + 32) : _PB_N;
            int len = jend - j;
            DATA_TYPE acc[32];

            for (jj = 0; jj < len; jj++)
              acc[jj] = SCALAR_VAL(0.0);

            for (ii = 0; ii < _PB_M; ii++)
              {
                DATA_TYPE q = Q[ii][k];
#pragma omp simd
                for (jj = 0; jj < len; jj++)
                  acc[jj] += q * A[ii][j + jj];
              }

            for (jj = 0; jj < len; jj++)
              R[k][j + jj] = acc[jj];

            for (ii = 0; ii < _PB_M; ii++)
              {
                DATA_TYPE q = Q[ii][k];
#pragma omp simd
                for (jj = 0; jj < len; jj++)
                  A[ii][j + jj] = A[ii][j + jj] - q * acc[jj];
              }
          }
      }
  }
#pragma endscop

}


