/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      x[i] = 0;
      y[i] = 0;
      b[i] = (i+1)/fn/2.0 + 4;
    }

  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite. */
  /* not necessary for LU, but using same code as cholesky */
  int r,s,t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      (POLYBENCH_ARRAY(B))[r][s] = 0;
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	(POLYBENCH_ARRAY(B))[r][s] += A[r][t] * A[s][t];
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	A[r][s] = (POLYBENCH_ARRAY(B))[r][s];
  POLYBENCH_FREE_ARRAY(B);

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;

  DATA_TYPE w;

#pragma scop
  {
    const int nn = _PB_N;
    const int LU_B = 32;   /* panel / block width in k */
    const int LU_JT = 64;  /* column tile width for U block-row update */

    /* Blocked right-looking LU. Every element A[i][j] receives the
       subtractions A[i][k]*A[k][j] in ascending k order (and the division
       by A[j][j] after all k<j updates for j<i), exactly as in the
       original formulation, so results are bitwise identical. */
#pragma omp parallel private(i, j, k)
    {
      for (int kb = 0; kb < nn; kb += LU_B) {
        int kend = (kb + LU_B < nn) ? kb + LU_B : nn;

        /* 1. Factor the diagonal block (small, sequential). */
#pragma omp single
        {
          for (k = kb; k < kend; k++) {
            for (i = k + 1; i < kend; i++) {
              A[i][k] = A[i][k] / A[k][k];
              DATA_TYPE a = A[i][k];
              for (j = k + 1; j < kend; j++)
                A[i][j] -= a * A[k][j];
            }
          }
        }

        /* 2. Update U block-row (rows kb+1..kend-1, cols >= kend),
              independent across column tiles. */
#pragma omp for schedule(static)
        for (int jt = kend; jt < nn; jt += LU_JT) {
          int jend = (jt + LU_JT < nn) ? jt + LU_JT : nn;
          for (int ii = kb + 1; ii < kend; ii++) {
            for (int kk = kb; kk < ii; kk++) {
              DATA_TYPE a = A[ii][kk];
#pragma omp simd
              for (int jj = jt; jj < jend; jj++)
                A[ii][jj] -= a * A[kk][jj];
            }
          }
        }

        /* 3. Fused panel (L columns kb..kend-1) + trailing update for
              rows >= kend, independent across rows. */
#pragma omp for schedule(static)
        for (int ii = kend; ii < nn; ii++) {
          for (int kk = kb; kk < kend; kk++) {
            A[ii][kk] = A[ii][kk] / A[kk][kk];
            DATA_TYPE a = A[ii][kk];
#pragma omp simd
            for (int jj = kk + 1; jj < nn; jj++)
              A[ii][jj] -= a * A[kk][jj];
          }
        }
      }
    }
  }

  for (i = 0; i < _PB_N; i++) {
     w = b[i];
     for (j = 0; j < i; j++)
        w -= A[i][j] * y[j];
     y[i] = w;
  }

   for (i = _PB_N-1; i >=0; i--) {
     w = y[i];
     for (j = i+1; j < _PB_N; j++)
        w -= A[i][j] * x[j];
     x[i] = w / A[i][i];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


